import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const c="/ascendc.github.io/pr/5487/assets/griddim_config_small_shape.D-V9LQfJ.png",g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMT算子性能优化","link":"/guide/operator_practice/simt_operator_optimization/simt_operator_optimization"},{"text":"执行配置","link":"/guide/operator_practice/simt_operator_optimization/execution_config/thread_block_config"},{"text":"线程块数量配置优化","link":"/guide/operator_practice/simt_operator_optimization/execution_config/thread_block_config"}]},"headers":[],"relativePath":"guide/operator_practice/simt_operator_optimization/execution_config/thread_block_config.md","filePath":"guide/operator_practice/simt_operator_optimization/execution_config/thread_block_config.md","outlineHeaders":[{"level":2,"title":"大数据量场景","slug":"大数据量场景","link":"#大数据量场景"},{"level":2,"title":"小数据量场景","slug":"小数据量场景","link":"#小数据量场景"}],"lastUpdated":1787798726000}'),t={name:"guide/operator_practice/simt_operator_optimization/execution_config/thread_block_config.md"};function e(i,s,o,d,r,_){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>线程块数量配置优化</h1><p>【优先级】高</p><p>【描述】SIMT编程模式下，通过<code>&lt;&lt;&lt;...&gt;&gt;&gt;</code>配置启动核函数（Kernel）的线程块数量，即<code>gridDim</code>，这些线程块最终被调度到硬件的Vector Core（物理核）上执行。由于硬件限制，一个物理核同一时刻只能驻留并执行一个线程块，每个线程块的启动和调度都会引入固定开销。当线程块数量远超物理核数时，需要启动调度的线程块数量大幅增加，调度的固定开销累积明显；线程块数量不足时，物理核闲置、并行核数不足、单核工作量增加，会显著影响耗时。此外数据规模越小、每个核工作量越少，调度固定开销占比越高，最优线程块数量会发生变化。因此，线程块数量应结合物理核数与数据规模设置。</p><p>线程块数量与物理核数的关系会影响调度开销：当线程块数量 ≤ 物理核数时，所有线程块可以一次性占用全部物理核并行执行，需要启动调度的线程块较少、固定开销有限；当线程块数量 &gt; 物理核数时，超出物理核数的线程块需等待前序线程块执行完成后再调度，需要启动和调度的线程块数量继续增加，多线程块启动和调度的固定开销开始明显累积，调度开销随线程块数量增大而上升。</p><p>物理核数可以在运行期通过<a href="https://www.hiascend.com/document/detail/zh/CANNCommunityEdition/latest/API/runtimeapi/aclcppdevg_03_1867.html">aclrtGetDeviceInfo</a>查询。</p><blockquote><p>注：在下面的两个场景中，实测的物理核数均为64。</p></blockquote><p>确定物理核数后，还需结合数据规模来设置线程块数量。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明 数据规模的“大”与“小”没有绝对界限，下文中两个场景只是两个量级上的代表，真正可靠的做法是以物理核数为起点实测尝试。</p><p>一个可参考的直觉是：全部物理核一次大约能并行处理“物理核数 × 单核最大线程数”个线程。数据量远大于这个量级时，将线程块数量设为物理核数就能充分发挥硬件算力；数据量与之相当甚至更小时，调度固定开销在总耗时中的占比变得敏感，最优线程块数量不再显而易见，需要使用msOpProf工具实测。</p></div><p>本优化方法对应的样例请参见<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/03_simt_api/03_best_practices/01_execution_conf_optimizations/grid_dim_config/README.md">核函数（Kernel）的启动配置性能调优样例</a>。</p><h2 id="大数据量场景">大数据量场景<a class="header-anchor" href="#大数据量场景">​</a></h2><p>下面以Gather算子为例，对比大数据量场景（<code>1024*2048</code>，即2097152个元素）下不同线程块数量配置的性能差异。</p><p>【反例】一个线程处理一个元素，随数据量增加线程块个数，导致需要启动和调度的线程块大幅增加。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 基础写法：每个线程只处理1个元素，无for循环</span>
<span class="c1">// 要求gridDim.x * blockDim.x == 元素总数(本样例1024 * 2048 == 2097152)</span>
<span class="n">__global__</span><span class="w"> </span><span class="nf">__launch_bounds__</span><span class="p">(</span><span class="n">MAX_THREAD_NUM</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">gather_naive_kernel</span><span class="p">(</span>
<span class="w">    </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="o">*</span><span class="w"> </span><span class="n">index</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">output</span><span class="p">,</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">input_total_length</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">index_total_length</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">global_idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>

<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">gather_idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">index</span><span class="p">[</span><span class="n">global_idx</span><span class="p">];</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">gather_idx</span><span class="w"> </span><span class="o">&gt;=</span><span class="w"> </span><span class="n">input_total_length</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">gather_idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="n">output</span><span class="p">[</span><span class="n">global_idx</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">input</span><span class="p">[</span><span class="n">gather_idx</span><span class="p">];</span>
<span class="p">}</span>

<span class="n">gather_naive_kernel</span><span class="o">&lt;&lt;&lt;</span><span class="mi">1024</span><span class="p">,</span><span class="w"> </span><span class="n">INDEX_WIDTH</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span>
<span class="w">    </span><span class="n">input_device</span><span class="p">,</span><span class="w"> </span><span class="n">index_device</span><span class="p">,</span><span class="w"> </span><span class="n">output_device</span><span class="p">,</span>
<span class="w">    </span><span class="n">input_total_length</span><span class="p">,</span><span class="w"> </span><span class="n">index_total_length</span><span class="p">);</span>
</code></pre></div><p>上述实现让每个线程处理唯一一个元素，因此线程块数量为：<code>元素总数 / 单核线程数 = 2097152 / 2048 = 1024</code>，多线程块下启动和调度的固定开销明显累积。该实现的性能数据如下：</p><table><thead><tr><th align="center">线程块数量</th><th align="center">Task Duration（us）</th></tr></thead><tbody><tr><td align="center">1024</td><td align="center">78.289</td></tr></tbody></table><p>【正例】<strong>一个线程处理多个元素</strong>，通过减少线程块数量，来减少调度开销。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 优化写法：线程以总线程数为步长跨步遍历整个数组，处理多个元素</span>
<span class="n">__global__</span><span class="w"> </span><span class="nf">__launch_bounds__</span><span class="p">(</span><span class="n">MAX_THREAD_NUM</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">gather_strided_kernel</span><span class="p">(</span>
<span class="w">    </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="o">*</span><span class="w"> </span><span class="n">index</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">output</span><span class="p">,</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">input_total_length</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">index_total_length</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">global_idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">gridDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>

<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">global_idx</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">index_total_length</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="n">stride</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">gather_idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">index</span><span class="p">[</span><span class="n">i</span><span class="p">];</span>
<span class="w">        </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">gather_idx</span><span class="w"> </span><span class="o">&gt;=</span><span class="w"> </span><span class="n">input_total_length</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">            </span><span class="n">gather_idx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="w">        </span><span class="p">}</span>
<span class="w">        </span><span class="n">output</span><span class="p">[</span><span class="n">i</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">input</span><span class="p">[</span><span class="n">gather_idx</span><span class="p">];</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>

<span class="c1">// 线程块数量固定为物理核数64，每block仍取硬件上限2048线程</span>
<span class="n">gather_strided_kernel</span><span class="o">&lt;&lt;&lt;</span><span class="mi">64</span><span class="p">,</span><span class="w"> </span><span class="n">MAX_THREAD_NUM</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span>
<span class="w">    </span><span class="n">input_device</span><span class="p">,</span><span class="w"> </span><span class="n">index_device</span><span class="p">,</span><span class="w"> </span><span class="n">output_device</span><span class="p">,</span>
<span class="w">    </span><span class="n">input_total_length</span><span class="p">,</span><span class="w"> </span><span class="n">index_total_length</span><span class="p">);</span>
</code></pre></div><p>上述实现的Gather算子功能与反例一致。只是调整线程块数量为64，每个线程块2048个线程，共启动131072个线程；为处理2097152个数据，每个线程需处理16个数据。该实现在大数据量场景下的性能数据如下：</p><table><thead><tr><th align="center">线程块数量</th><th align="center">Task Duration（us）</th></tr></thead><tbody><tr><td align="center">64</td><td align="center">58.583</td></tr></tbody></table><p>上述两种写法的性能数据汇总如下：</p><table><thead><tr><th align="center">写法</th><th align="center">线程块数量</th><th align="center">Task Duration（us）</th></tr></thead><tbody><tr><td align="center"><strong>单线程多数据</strong></td><td align="center"><strong>64</strong></td><td align="center"><strong>58.583</strong></td></tr><tr><td align="center">单线程单数据</td><td align="center">1024</td><td align="center">78.289</td></tr></tbody></table><p>根据Task Duration数据，处理相同的数据量时，采用一个线程处理多个数据写法，并将线程块数量从1024减少到64后，执行耗时从78.289us下降到58.583us，下降约25.2%，整体性能提升约1.34倍。减少线程块数量反而能提升性能，这是因为当线程块数量为1024时，超出物理核数量的线程块需要等待前序线程块执行完成后再调度，额外的启动和调度固定开销会明显增加。</p><h2 id="小数据量场景">小数据量场景<a class="header-anchor" href="#小数据量场景">​</a></h2><p>数据量较小时，最优线程块数量没有可以照搬的经验值，只能通过实测寻找。</p><p>【反例】小数据量场景下沿用“使用全部物理核”的经验，把线程块数量直接设为物理核数64。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// kernel与大数据量场景正例完全相同(gather_strided_kernel)，仅将数据量调整为小数据量场景16384</span>
<span class="c1">// 直接沿用&quot;使用全部物理核&quot;的经验，线程块数量=64</span>
<span class="n">gather_strided_kernel</span><span class="o">&lt;&lt;&lt;</span><span class="mi">64</span><span class="p">,</span><span class="w"> </span><span class="n">MAX_THREAD_NUM</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span>
<span class="w">    </span><span class="n">input_device</span><span class="p">,</span><span class="w"> </span><span class="n">index_device</span><span class="p">,</span><span class="w"> </span><span class="n">output_device</span><span class="p">,</span>
<span class="w">    </span><span class="n">input_total_length</span><span class="p">,</span><span class="w"> </span><span class="n">index_total_length</span><span class="p">);</span>
</code></pre></div><p>上述实现对小数据量场景也使用64个物理核，每核只处理<code>16384 / 64 = 256</code>个元素，此时计算本身耗时很短，启动64个线程块带来的调度固定开销在总耗时中占比升高。该实现在小数据量场景下的性能数据如下：</p><table><thead><tr><th align="center">线程块数量</th><th align="center">每个线程块的线程数</th><th align="center">Task Duration（us）</th></tr></thead><tbody><tr><td align="center">64</td><td align="center">256</td><td align="center">4.133</td></tr></tbody></table><p>【正例】小数据量场景下不直接沿用“使用全部物理核”的经验，而是设置多档线程块数量实测，取Task Duration最低点。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// kernel不变，仅设置不同线程块数量，通过msOpProf工具实测性能</span>
<span class="c1">// 小数据量场景(16384)实测：线程块数量取4 / 8 / 16 / 32 / 64，最低点在线程块数量=32</span>
<span class="n">gather_strided_kernel</span><span class="o">&lt;&lt;&lt;</span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="n">MAX_THREAD_NUM</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span>
<span class="w">    </span><span class="n">input_device</span><span class="p">,</span><span class="w"> </span><span class="n">index_device</span><span class="p">,</span><span class="w"> </span><span class="n">output_device</span><span class="p">,</span>
<span class="w">    </span><span class="n">input_total_length</span><span class="p">,</span><span class="w"> </span><span class="n">index_total_length</span><span class="p">);</span>
</code></pre></div><p>上述实现的kernel不变，仅在4到64之间设置不同的线程块数量并逐档实测。每个线程块的线程数取每个线程块需处理的数据量与硬件线程数上限2048中的较小值：当每个线程块需处理的数据量不小于2048时，线程数设为2048；小于2048时，线程数降为实际需处理的数据量。小数据量场景下Task Duration随线程块数量变化呈“先降后升”的趋势，本样例实测最优线程块数量为32，而非使用全部物理核的线程块数量64。</p><table><thead><tr><th align="center">线程块的数量</th><th align="center">每个线程块的线程数</th><th align="center">Task Duration（us）</th></tr></thead><tbody><tr><td align="center">4</td><td align="center">2048</td><td align="center">10.831</td></tr><tr><td align="center">8</td><td align="center">2048</td><td align="center">6.569</td></tr><tr><td align="center">16</td><td align="center">1024</td><td align="center">4.500</td></tr><tr><td align="center">32</td><td align="center">512</td><td align="center"><strong>3.696</strong></td></tr><tr><td align="center">64</td><td align="center">256</td><td align="center">4.133</td></tr></tbody></table><p>下图直观展示了上表中Task Duration随线程块数量的变化趋势：</p><img src="`+c+'" alt="小数据量场景（16384） Task Duration随线程块数量的变化" width="480"><p>根据Task Duration数据，在本样例的小数据量场景下，线程块数量从4依次增加到8、16、32时耗时持续下降（10.831 → 6.569 → 4.500 → 3.696us）。这是因为线程块中的线程并不是全部在并行执行，而是以warp为单位调度执行，单核上warp过多时会产生排队等待，线程块数量较小时，每个线程块需要启动更多线程，等待时间更明显；增加线程块数量可以降低单个线程块的线程数并提高并行核数，因此收益明显。当线程块数量从32增加到64时，耗时从3.696us上升到4.133us，说明在该数据规模下继续增加线程块数量带来的调度固定开销超过并行收益。因此，小数据规模场景下需通过实测确定最优线程块数量。</p><p>【总结】SIMT算子的线程块数量配置应结合物理核数与数据规模来设置。</p><p>一般原则是：</p><ul><li><strong>大数据量场景优先匹配物理核数</strong>：当数据量远大于“物理核数 × 单核最大线程数”这个量级时，线程块数量直接使用物理核数，既避免线程块数量不足导致单核工作量过重，也避免线程块数量过多带来更多线程块启动和调度开销。</li><li><strong>小数据量场景需实测线程块数量</strong>：当数据量与“物理核数 × 单核最大线程数”相当甚至更小、每核工作量很小时，启动更多核带来的调度固定开销会超过有效计算收益，最优线程块数量无法预判，必须通过msOpProf工具实测性能，选择Task Duration较低的线程块数量配置。</li></ul></article></div>',1)])])}const w=a(t,[["render",e]]);export{g as __pageData,w as default};
